  "candidates": [
    {
      "id": "P-API",
      "item_revision": 2,
      "content": "Preserve supported API compatibility or explicitly document and authorize the breaking change.",
      "condition": "When changing an API or externally consumed interface with existing compatibility expectations.",
      "activation": {
        "mode": "on_tags",
        "any": [
          "code.api_change"
        ]
      },
      "strength": "must"
    },
    {
      "id": "P-ARGUMENT",
      "item_revision": 2,
      "content": "Identify assumptions, supporting evidence, counterexamples, and consequences relevant to the conclusion.",
      "condition": "When assessing the validity, assumptions, evidence, or consequences of an argument or decision.",
      "activation": {
        "mode": "on_tags",
        "any": [
          "reasoning.argument"
        ]
      },
      "strength": "should"
    },
    {
      "id": "P-COMPARABLE",
      "item_revision": 2,
      "content": "Compare compatible periods, definitions and denominators, and disclose missing values.",
      "condition": "When comparing company performance using numeric evidence. Exclude translation and proofreading that preserve facts and analysis.",
      "activation": {
        "mode": "always"
      },
      "strength": "must"
    },
    {
      "id": "P-DEBUG",
      "item_revision": 2,
      "content": "Reproduce the failure and test a concrete cause before changing code.",
      "condition": "When investigating an unexplained defect or failing behavior and identifying its cause. Exclude requests that only explain already established results.",
      "activation": {
        "mode": "on_tags",
        "any": [
          "code.debugging"
        ]
      },
      "strength": "should"
    },
    {
      "id": "P-ELICIT",
      "item_revision": 2,
      "content": "Separate outcomes, constraints, and acceptance criteria. Preserve valid existing requirements when adding new ones.",
      "condition": "When discovering or clarifying requirements and acceptance criteria for a project or decision.",
      "activation": {
        "mode": "on_tags",
        "any": [
          "requirements.discovery"
        ]
      },
      "strength": "should"
    },
    {
      "id": "P-KNOWLEDGE",
