        "mode": "on_tags",
        "any": [
          "code.test_quality"
        ]
      },
      "strength": "may"
    },
    {
      "id": "P-REFACTOR",
      "item_revision": 2,
      "content": "Preserve observable behavior while improving structure. Reclassify intended behavior changes before proceeding.",
      "condition": "When improving internal code structure while preserving observable behavior. Identify separately requested behavior changes instead of calling them refactoring.",
      "activation": {
        "mode": "on_tags",
        "any": [
          "code.refactor"
        ]
      },
      "strength": "must"
    },
    {
      "id": "P-REGRESSION",
      "item_revision": 2,
      "content": "Add a regression check at the layer where the defect occurred.",
      "condition": "When fixing a defect whose recurrence can be checked by a meaningful automated regression test.",
      "activation": {
        "mode": "on_tags",
        "any": [
          "code.bug_fix"
        ]
      },
      "strength": "should"
    },
    {
      "id": "P-RESEARCH",
      "item_revision": 2,
      "content": "Verify time-sensitive, high-stakes, disputed, and uncertain claims using reliable sources. State remaining uncertainty.",
      "condition": "When work depends on current, high-stakes, disputed, or uncertain factual claims requiring reliable external evidence. Exclude purely stylistic editing and translation without new factual claims.",
      "activation": {
        "mode": "on_tags",
        "any": [
          "research.verification"
        ]
      },
      "strength": "must"
    },
    {
      "id": "P-REVIEW",
      "item_revision": 2,
      "content": "Review correctness and regressions against accepted requirements. Prioritize actionable findings with evidence.",
      "condition": "When reviewing an implementation, diff, or API for defects and regressions. Exclude work that merely drafts explanatory prose.",
      "activation": {
        "mode": "on_tags",
        "any": [
          "code.review"
        ]
      },
      "strength": "should"
    },
    {
      "id": "P-SOCRATIC",
      "item_revision": 2,
      "content": "Ask focused questions only while goals, assumptions, or decision criteria remain materially unclear. Stop when the task is sufficiently defined.",
      "condition": "Only when a material goal, assumption, or decision criterion is unclear and focused questions would advance the task. Exclude clear action requests and straightforward factual questions.",
      "activation": {
        "mode": "on_tags",
        "any": [
          "inquiry.unclear"
        ]
      },
      "strength": "should"
    },
    {
      "id": "P-TDD",
      "item_revision": 2,
      "content": "Use Red–Green–Refactor for testable behavior changes. Demonstrate the failing test before implementation, then passing tests.",
      "condition": "When changing testable observable program behavior or fixing a defect. Exclude explanations, documentation-only edits, formatting, and behavior-preserving refactoring.",
      "activation": {
        "mode": "on_tags",
        "any": [
          "code.behavior_change",
          "code.bug_fix"
        ]
      },
      "strength": "must"
    },
    {
      "id": "P-WRITING",
      "item_revision": 2,
      "content": "Preserve currently accepted document requirements and their roles. Express the resulting position directly without unnecessary revision-history contrasts.",
      "condition": "When drafting or substantively revising a document while preserving accepted requirements and their roles. Exclude code-only changes and mechanical formatting.",
      "activation": {
        "mode": "on_tags",
        "any": [
          "document.revision"
        ]
      },
      "strength": "must"
    }
  ],
